import React, { useEffect, useState } from "react";

import Dashboard from "./Dashboard";
import TopBar from "./TopBar";
import apiClient from "../api";

const Home = () => {
  const [user, setUser] = useState(null);
  const [isCheckingSession, setIsCheckingSession] = useState(true);
  const [sessionError, setSessionError] = useState("");
  const frontendUrl = process.env.REACT_APP_FRONTEND_URL || "http://localhost:3000";

  useEffect(() => {
    const controller = new AbortController();

    apiClient
      .get("/auth/me", { signal: controller.signal })
      .then((response) => setUser(response.data.user))
      .catch((error) => {
        if (error.code !== "ERR_CANCELED" && error.response?.status !== 401) {
          setSessionError("Unable to connect to the backend. Please try again.");
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setIsCheckingSession(false);
        }
      });

    return () => controller.abort();
  }, []);

  const handleLogout = async () => {
    try {
      await apiClient.post("/auth/logout");
      setUser(null);
      setSessionError("");
    } catch (error) {
      setSessionError(
        error.response?.data?.message || "Unable to sign out. Please try again."
      );
    }
  };

  if (isCheckingSession) {
    return <p role="status">Checking your account...</p>;
  }

  if (!user) {
    return (
      <main className="account-required">
        <h1>Sign in required</h1>
        <p>{sessionError || "Sign in to see your private trading dashboard."}</p>
        <a href={`${frontendUrl}/login`}>Sign in</a>
        {" · "}
        <a href={`${frontendUrl}/signup`}>Create account</a>
      </main>
    );
  }

  return (
    <>
      {sessionError && <p role="alert">{sessionError}</p>}
      <TopBar user={user} onLogout={handleLogout} />
      <Dashboard />
    </>
  );
};

export default Home;
